    "statements": [
        "读整时时，分针指向12。",
        "读整时时，时针指向几就是几时。",
        "读半时时，分针指向6。",
        "读半时时，时针位于两个相邻数字之间。",
        "读半时时，时针刚经过几，就读作几时半。",
        "例如时针在3和4之间、分针指6，是3时半。"
    ]
}
